func PromptBool(
	out io.Writer,
	in io.Reader,
	prompt string,
	defaultValue bool,
) bool {
	validBool := func(s string) error {
		if strings.TrimSpace(s) == "" {
			return nil
		}
		_, err := parseBool(s)
		return err
	}

	input := PromptString(
		out, in, prompt,
		boolToStr(defaultValue),
		validBool,
	)
	b, _ := parseBool(input)
	return b
}

// PromptPassword allows to prompt for a password.
// In must be the fd of a tty.
func PromptPassword(
	out io.Writer,
	in uintptr,
	prompt string,
	validator func(input string) error,
) (string, error) {
	for {
		_, _ = fmt.Fprint(out, prompt)
		pwd, err := term.ReadPassword(in)
