			wantFound: true,
		},
		{
			name:      "no trailer",
			message:   "Simple commit message",
			wantDir:   "",
			wantFound: false,
		},
		{
			name:      "trailer with extra spaces",
			message:   "Message\n\nEntire-Metadata:   .entire/metadata/xyz   \n",
			wantDir:   ".entire/metadata/xyz",
			wantFound: true,
		},
	}

	for _, tt := range tests {
