	if !strings.Contains(err.Error(), "timed out") {
		t.Errorf("error = %q, want it to name a timeout", err)
	}
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Errorf("error = %q, want it to wrap context.DeadlineExceeded", err)
	}
}
