	if err != nil {
		t.Fatalf("ResolveAgentForResume() error = %v", err)
	}

	var output bytes.Buffer
	if err := displayRestoredSessions(&output, []strategy.RestoredSession{session}); err != nil {
		t.Fatalf("displayRestoredSessions() error = %v", err)
	}

